import{bV as i,aL as a,u as p,G as e}from"./chunks/framework.DT-LCgF3.js";const t="/Li6Daily/assets/img_1.CkRBrjdo.png",l="/Li6Daily/assets/img_2.c7l4A24c.png",n="/Li6Daily/assets/img_3.BZHeIThS.png",r="/Li6Daily/assets/img_4.CxRCq5tc.png",o="/Li6Daily/assets/img_5.DPT2ZrF3.png",d="/Li6Daily/assets/img_6.8BUBInPX.png",g="/Li6Daily/assets/img_7.BRGdHKbR.png",c="/Li6Daily/assets/img_8.CaBNXyvy.png",h="/Li6Daily/assets/img_9.Cy7ZDdmJ.png",m="/Li6Daily/assets/img_10.CSfBXfWV.png",_="/Li6Daily/assets/img_11.B5qMcNrH.png",k="/Li6Daily/assets/img_12.CNC7WMU4.png",F="/Li6Daily/assets/img_13.poQm0OU-.png",y="/Li6Daily/assets/img_14.BDbS65WN.png",b="/Li6Daily/assets/img_15.Dxk0owli.png",S="/Li6Daily/assets/img_16.KF4aOuaY.png",u="/Li6Daily/assets/img_17.BTej9HS3.png",C="/Li6Daily/assets/img_18.D8HLbAds.png",P="/Li6Daily/assets/img_19.DZrgXceq.png",v="/Li6Daily/assets/img_20.CzHhm3Jj.png",B="/Li6Daily/assets/img_21.DNeEZU5r.png",f="/Li6Daily/assets/img_22.CVFw541i.png",I="/Li6Daily/assets/img_23.CWTtmD1q.png",D="/Li6Daily/assets/img_24.Cc3iTEjV.png",T="/Li6Daily/assets/img_25.e5rXOt2l.png",L="/Li6Daily/assets/img_26.BHumK8db.png",z="/Li6Daily/assets/img_27.JRwxM1H-.png",U=JSON.parse('{"title":"文件服务器协议搭建汇总（FTP/SFTP/S3/SMB）","description":"","frontmatter":{"date":"2026-08-04T10:30:00.000Z","title":"文件服务器协议搭建汇总（FTP/SFTP/S3/SMB）","permalink":"/pages/a1b2c3","categories":["Protocol","文件传输协议"]},"headers":[],"relativePath":"Protocol/01.文件传输协议/04.文件服务器协议汇总.md","filePath":"Protocol/01.文件传输协议/04.文件服务器协议汇总.md","lastUpdated":1785828778000}'),E={name:"Protocol/01.文件传输协议/04.文件服务器协议汇总.md"};function w(q,s,x,O,H,M){return a(),p("div",null,[...s[0]||(s[0]=[e('<h1 id="文件服务器协议搭建汇总-ftp-sftp-s3-smb" tabindex="-1">文件服务器协议搭建汇总（FTP/SFTP/S3/SMB） <a class="header-anchor" href="#文件服务器协议搭建汇总-ftp-sftp-s3-smb" aria-label="Permalink to &quot;文件服务器协议搭建汇总（FTP/SFTP/S3/SMB）&quot;">​</a></h1><blockquote><p>本文根据原始教程文档转写，按原教程顺序保留文字与截图，未做发散。 其中 FTP（IIS）与 OpenSSH-SFTP 部分与站内已有《FTP协议》《sftp》文章存在重叠，本汇总文档新增内容为 mini-sftp-server、S3（MinIO）、SMB。</p></blockquote><h2 id="ftp-协议-windows-server-2016-iis" tabindex="-1">FTP 协议（Windows Server 2016 IIS） <a class="header-anchor" href="#ftp-协议-windows-server-2016-iis" aria-label="Permalink to &quot;FTP 协议（Windows Server 2016 IIS）&quot;">​</a></h2><p>FTP 协议服务端搭建的方式包含 IIS、FileZilla 等，下述方式仅为 WindowsServer 2016 版本 IIS 方式，如有其他系统版本 IIS，操作方式类似。</p><p>创建一个 ftpuser 用户用于客户端登录。</p><p>右键点击开始图标，选择计算机管理。</p><p>点击本地用户和组，选择用户。</p><p>右键点击用户，选择新用户。</p><p><img src="'+t+'" alt="04.文件服务器协议汇总 截图 1" loading="lazy"></p><p>输入用户信息，下方勾选栏选项如图配置，点击创建。</p><p><img src="'+l+'" alt="04.文件服务器协议汇总 截图 2" loading="lazy"></p><p>进入系统搜索“服务器管理器”，然后打开，（其他 Windows 版本搜索 IIS 管理器即可）。</p><p><img src="'+n+'" alt="04.文件服务器协议汇总 截图 3" loading="lazy"></p><p>进入“服务器管理器”页面，点击右上角的工具，选择“IIS 管理器”，其他版本例如 Windows10 可直接在系统左下角点击搜索栏或者通过快捷键 Win+S 打开搜索栏，搜索关键字“IIS 管理器”，根据提示打开 Internet Information Services (IIS) 管理器。</p><p><img src="'+r+'" alt="04.文件服务器协议汇总 截图 4" loading="lazy"></p><p>进入 IIS 管理器后，依次点击点开左侧视图列表，随后右键单击“网站”，选择添加 FTP 站点。</p><p><img src="'+o+'" alt="04.文件服务器协议汇总 截图 5" loading="lazy"></p><p>输入必要信息，站点名称和物理路径，点击下一步。</p><p>Tips: 站点名称作为名称标识，可以随意修改。</p><p>物理路径作为 FTP 服务端的根目录，即登录后的目录。</p><p><img src="'+d+'" alt="04.文件服务器协议汇总 截图 6" loading="lazy"></p><p>进行绑定 IP、端口设置，IP 地址选择本机 IP，端口默认 21，不启用虚拟主机名，关闭 SSL 证书，开启自动启动 FTP 站点，点击下一步。</p><p><img src="'+g+'" alt="04.文件服务器协议汇总 截图 7" loading="lazy"></p><p>进行身份验证配置，开启基本身份验证，关闭匿名登录，授权给指定用户访问，下方输入对应步骤 1 中的用户名，权限配置为允许读取和写入，点击完成。</p><p><img src="'+c+'" alt="04.文件服务器协议汇总 截图 8" loading="lazy"></p><h2 id="sftp-协议" tabindex="-1">SFTP 协议 <a class="header-anchor" href="#sftp-协议" aria-label="Permalink to &quot;SFTP 协议&quot;">​</a></h2><h3 id="_2-1-mini-sftp-server" tabindex="-1">2.1 mini-sftp-server <a class="header-anchor" href="#_2-1-mini-sftp-server" aria-label="Permalink to &quot;2.1 mini-sftp-server&quot;">​</a></h3><p>单击运行桌面可执行程序 mini-sftp-server.exe。</p><p><img src="'+h+'" alt="04.文件服务器协议汇总 截图 9" loading="lazy"></p><p>输入必要信息，点击 Options 配置说明如下，配置完成后，点击 OK。</p><p>User: sftp 用户名</p><p>Password: 密码</p><p>Port: 端口</p><p>Root path: 访问后的根目录</p><p>Enable zlib 是否允许客户端开启压缩</p><p>Enable nagle 是否允许客户端启用 nagle 算法</p><p>Enable scp 允许使用客户端使用 scp</p><p>FIPS mode 切换 FIPS 模式</p><p>List hidden files 列出隐藏的文件</p><p>UTF-8 编码支持中文</p><p>IP/Address 服务端暴露可访问的 IP</p><p><img src="'+m+'" alt="04.文件服务器协议汇总 截图 10" loading="lazy"></p><p>点击 start 启动。</p><p><img src="'+_+'" alt="04.文件服务器协议汇总 截图 11" loading="lazy"></p><h3 id="openssh" tabindex="-1">OpenSSH <a class="header-anchor" href="#openssh" aria-label="Permalink to &quot;OpenSSH&quot;">​</a></h3><p>安装之前，把之前的都卸载干净。</p><ol><li>把下载好的 OpenSSH-Win64.zip 文件解压，把 OpenSSH 整个目录复制到 <code>C:\\Program Files</code>（避免未知错误）。</li><li>把 <code>C:\\Program Files\\OpenSSH-Win64</code> 添加到环境变量。</li><li>管理员启动 cmd，进入到 <code>C:\\Program Files\\OpenSSH-Win64</code>，执行如下命令：</li></ol><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">powershell.exe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ExecutionPolicy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bypass</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -File</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install-sshd.ps1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>开放 22 端口：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netsh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> advfirewall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name=sshd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dir=in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> action=allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protocol=TCP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localport=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">22</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>配置开机自启服务：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sshd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auto</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>开启服务：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">net</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sshd</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>替换配置文件，位置 <code>C:\\ProgramData\\ssh\\sshd_config</code>。</p><h2 id="s3-协议-minio" tabindex="-1">S3 协议（MinIO） <a class="header-anchor" href="#s3-协议-minio" aria-label="Permalink to &quot;S3 协议（MinIO）&quot;">​</a></h2><p>使用 minio 提供 S3 协议的服务端。</p><p>桌面点击 S3 目录，单击 <code>start-s3-server.bat</code> 执行启动。</p><p><img src="'+k+'" alt="04.文件服务器协议汇总 截图 12" loading="lazy"></p><p>可通过如下所示的地址进行访问，默认的账户和密码均为 <code>minioadmin</code>。</p><p><img src="'+F+'" alt="04.文件服务器协议汇总 截图 13" loading="lazy"></p><p>打开浏览器输入访问 url，依次单击左侧导航栏 Identity → Users，然后单击右侧 Create User+，进行用户创建。</p><p><img src="'+y+'" alt="04.文件服务器协议汇总 截图 14" loading="lazy"></p><p>输入创建的用户信息，勾选下方用户策略，点击 Save。</p><p>ConsoleAdmin : 允许用户完全访问 MinIO 控制台</p><p>Diagnostics 允许用户执行诊断操作，例如获取服务器的状态和性能信息</p><p>Readonly: 允许用户读取存储桶中的所有对象，但不能进行修改</p><p>Writeonly: 允许用户向存储桶中写入对象，但不能读取或列出对象</p><p>readwrite: 允许用户对存储桶中的所有对象执行读写操作</p><p><img src="'+b+'" alt="04.文件服务器协议汇总 截图 15" loading="lazy"></p><p>保存完成后，客户端可使用该用户进行操作。</p><h2 id="smb-协议" tabindex="-1">SMB 协议 <a class="header-anchor" href="#smb-协议" aria-label="Permalink to &quot;SMB 协议&quot;">​</a></h2><p>依照 FTP 协议创建用户的流程，同样创建一个 smb 用户用于客户端登录。</p><p>在空闲磁盘中创建一个目录作为 smb 共享的根目录。</p><p>搜索服务器管理器，并进入。</p><p><img src="'+S+'" alt="04.文件服务器协议汇总 截图 16" loading="lazy"></p><p>进入后点击右上角工具，选择计算机管理，其他系统版本可直接 win+s 搜索计算机管理。</p><p><img src="'+u+'" alt="04.文件服务器协议汇总 截图 17" loading="lazy"></p><p>依次点击计算机管理左侧导航栏的共享文件 &gt; 共享，右键单击右侧空白处选择新建共享。</p><p><img src="'+C+'" alt="04.文件服务器协议汇总 截图 18" loading="lazy"></p><p>进入创建共享文件夹向导，点击下一步。</p><p><img src="'+P+'" alt="04.文件服务器协议汇总 截图 19" loading="lazy"></p><p>文件夹路径选择刚才新建的目录，点击下一步。</p><p><img src="'+v+'" alt="04.文件服务器协议汇总 截图 20" loading="lazy"></p><p>配置共享名，点击下一步。</p><p><img src="'+B+'" alt="04.文件服务器协议汇总 截图 21" loading="lazy"></p><p>配置共享文件夹权限，进行自定义权限配置，点击添加刚才创建的用户，赋予权限。</p><p><img src="'+f+'" alt="04.文件服务器协议汇总 截图 22" loading="lazy"></p><p>点击添加后弹出选择用户或组，点击高级。</p><p><img src="'+I+'" alt="04.文件服务器协议汇总 截图 23" loading="lazy"></p><p>点击立即查找，在下方搜索结果中选择刚才创建的用户，点击确定。</p><p><img src="'+D+'" alt="04.文件服务器协议汇总 截图 24" loading="lazy"></p><p>返回后，可以看到对象名称后，继续点击确定按钮。</p><p><img src="'+T+'" alt="04.文件服务器协议汇总 截图 25" loading="lazy"></p><p>赋予用户完全控制权限。</p><p><img src="'+L+'" alt="04.文件服务器协议汇总 截图 26" loading="lazy"></p><p>同时删除掉 Everyone 的权限，只留下所选用户，这样其他用户就无法通过远程连接方式访问共享目录。</p><p><img src="'+z+'" alt="04.文件服务器协议汇总 截图 27" loading="lazy"></p>',98)])])}const N=i(E,[["render",w]]);export{U as __pageData,N as default};
